def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
      - Multiplos de 3 son 'Fizz'
      - Multiplos de 5 son 'Buzz'
      - Multiplos de 3 y 5 son 'FizzBuzz'
      - Los demás son los números como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra en minúscula y las siguientes con la inicial en mayúscula,
    sin guiones bajos.

    Args:
        s: El texto a convertir.

    Returns:
        El texto convertido en camelCase.
    """
    words = s.split()
    result = []
    for word in words:
        if word:
            if len(word) == 1:
                result.append(word)
            else:
                result.append(word[0].upper() + word[1:])
    return " ".join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    return [i for i in range(2, n + 1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: El texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False en caso contrario.

    Un texto vacío es considerado balanceado.
    """
    if not s:
        return True

    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in mapping:
            stack.append(char)
        elif char in mapping.values():
            if not stack:
                return False
            top = stack.pop()
            if top != mapping[char]:
                return False

    return len(stack) == 0

def anidar(plano: dict) -> dict:
    """
    Recursivamente convierte un diccionario de claves con puntos en un diccionario anidado.

    Ejemplo:
        {'a.b': 1} -> {'a': {'b': 1}}
        {'a.b.c': 2} -> {'a': {'b': {'c': 2}}}
        {'a.b.c.d': 3} -> {'a': {'b': {'c': {'d': 3}}}}

    Args:
        plano: Un diccionario donde las claves pueden contener puntos ('.')

    Returns:
        Un diccionario anidado con las claves descompuestas.
    """
    if not plano:
        return {}

    # Recursividad: si la clave tiene puntos, recursivamente descompone
    if '.' in plano:
        return {k.replace('.', '.'): anidar(plano[k]) for k in plano}

    # Caso base: si no hay puntos, devuelve el diccionario como está
    return plano

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a texto legible usando múltiplos de 1024.

    Unidades: B, KB, MB, GB.
    B va sin decimales, KB, MB, GB van con decimales.

    Args:
        n: Número entero en bytes.

    Returns:
        String formateada como 'n.B' o 'n.0 KB', 'n.0 MB', etc.
    """
    if n <= 0:
        return "0 B"

    if n <= 1024:
        return f"{n} B"
    elif n <= 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    elif n <= 1024 * 1024 * 1024:
        return f"{n / 1024 / 1024:.1f} MB"
    else:
        return f"{n / 1024 / 1024 / 1024:.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split('&'):
        if '=' in part:
            key, value = part.split('=', 1)
            result[key] = value
    return result

